export default (got) => {
    return {
        async list() {
            const devices = await got.get(`devices`).json();
            return devices.filter((d) => d.deviceType === 'occupancySensor');
        },
        async get({ id }) {
            const device = await got.get(`devices/${id}`).json();
            if (device.deviceType !== 'occupancySensor') {
                throw new Error('The requested device is not an occupancySensor');
            }
            return device;
        },
        async setOnDuration({ id, onDuration, }) {
            await got
                .patch(`devices/${id}`, {
                json: [
                    {
                        attributes: {
                            sensorConfig: {
                                onDuration,
                            },
                        },
                    },
                ],
            })
                .json();
        },
        async setScheduleOn({ id, scheduleOn, }) {
            await got
                .patch(`devices/${id}`, {
                json: [
                    {
                        attributes: {
                            sensorConfig: {
                                scheduleOn,
                            },
                        },
                    },
                ],
            })
                .json();
        },
        async setSchedule({ id, schedule, }) {
            await got
                .patch(`devices/${id}`, {
                json: [
                    {
                        attributes: {
                            sensorConfig: {
                                schedule,
                            },
                        },
                    },
                ],
            })
                .json();
        },
    };
};
